 "content": "def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    vals={v for row in g for v in row}
    bg=max(vals,key=lambda x:sum(row.count(x) for row in g))
    fg=[v for v in vals if v!=bg]
    if not fg:return g
    color=fg[0]
    original=[(r,c) for r in range(h) for c in range(w) if g[r][c]==color]
    # Connect aligned marks: fill intervening background cells in each row/column.
    for r in range(h):
        cols=[c for rr,c in original if rr==r]
        if len(cols)>1:
            for c in range(min(cols),max(cols)+1):
                if g[r][c]==bg:g[r][c]=2
    for c in range(w):
        rows=[r for r,cc in original if cc==c]
        if len(rows)>1:
            for r in range(min(rows),max(rows)+1):
                if g[r][c]==bg:g[r][c]=2
    return g

